CREATE OR REPLACE FUNCTION public.assign_nearby_searching_orders_on_rider_freed()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    v_rider RECORD;
    v_supabase_url text := 'https://yvwpchffctiagevpqgwy.supabase.co';
    v_service_role_key text;
BEGIN
    IF NEW.rider_id IS NULL THEN
        RETURN NEW;
    END IF;

    SELECT id, user_id, account_status, current_lat, current_lng, service_mode
    INTO v_rider
    FROM public.riders
    WHERE id = NEW.rider_id;

    IF NOT FOUND OR v_rider.account_status IS DISTINCT FROM 'online'::public.rider_account_status_enum THEN
        RETURN NEW;
    END IF;

    BEGIN
        SELECT decrypted_secret INTO v_service_role_key
        FROM vault.decrypted_secrets
        WHERE name = 'supabase_service_role_key'
        LIMIT 1;

        IF v_service_role_key IS NOT NULL THEN
            PERFORM net.http_post(
                url := v_supabase_url || '/rest/v1/rpc/assign_nearby_searching_orders_core',
                headers := jsonb_build_object(
                    'Content-Type', 'application/json',
                    'Authorization', 'Bearer ' || v_service_role_key,
                    'apikey', v_service_role_key
                ),
                body := jsonb_build_object(
                    'p_rider_id', v_rider.id,
                    'p_rider_user_id', v_rider.user_id,
                    'p_current_lat', v_rider.current_lat,
                    'p_current_lng', v_rider.current_lng,
                    'p_service_mode', v_rider.service_mode
                ),
                timeout_milliseconds := 5000
            );
        ELSE
            RAISE WARNING 'assign_nearby_searching_orders_on_rider_freed: vault secret "supabase_service_role_key" is not configured -- skipping async rematch for rider %', v_rider.id;
        END IF;
    EXCEPTION WHEN OTHERS THEN
        -- Never block the order's own completion/cancellation on the async enqueue itself failing
        -- -- the 15s redispatch cron (redispatch_stalled_searching_orders) and the next
        -- online-transition/new-order trigger remain independent backstops for this rider's next
        -- match either way.
        RAISE WARNING 'assign_nearby_searching_orders_on_rider_freed: failed to enqueue async rematch for rider %: %', v_rider.id, SQLERRM;
    END;

    RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.assign_new_order_to_nearby_online_riders()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    v_supabase_url text := 'https://yvwpchffctiagevpqgwy.supabase.co';
    v_service_role_key text;
BEGIN
    IF NEW.order_status != 'searching' THEN
        RETURN NEW;
    END IF;

    IF NEW.pickup_lat IS NULL OR NEW.pickup_lng IS NULL THEN
        RETURN NEW;
    END IF;

    BEGIN
        SELECT decrypted_secret INTO v_service_role_key
        FROM vault.decrypted_secrets
        WHERE name = 'supabase_service_role_key'
        LIMIT 1;

        IF v_service_role_key IS NOT NULL THEN
            PERFORM net.http_post(
                url := v_supabase_url || '/rest/v1/rpc/assign_new_order_to_nearby_online_riders_core',
                headers := jsonb_build_object(
                    'Content-Type', 'application/json',
                    'Authorization', 'Bearer ' || v_service_role_key,
                    'apikey', v_service_role_key
                ),
                body := jsonb_build_object(
                    'p_order_id', NEW.id
                ),
                timeout_milliseconds := 5000
            );
        ELSE
            RAISE WARNING 'assign_new_order_to_nearby_online_riders: vault secret "supabase_service_role_key" is not configured -- skipping async nearby-rider match for order %', NEW.id;
        END IF;
    EXCEPTION WHEN OTHERS THEN
        -- Never block the order's own creation on the async enqueue itself failing -- start-dispatch
        -- (fired independently by create-order) remains the primary, unaffected matching path either
        -- way; this trigger was always a latency optimization layered on top of it, never the only
        -- route to a match.
        RAISE WARNING 'assign_new_order_to_nearby_online_riders: failed to enqueue async nearby-rider match for order %: %', NEW.id, SQLERRM;
    END;

    RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.on_rider_assignment_change()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    v_rider_user_id uuid := NULL;
    v_order_type text := NULL;
    v_notification_type text := 'order_assignment';
BEGIN
    -- Notify when status is set or updated to 'sent'
    IF NEW.assignment_status = 'sent' AND (TG_OP = 'INSERT' OR OLD.assignment_status IS DISTINCT FROM 'sent') THEN
        SELECT user_id INTO v_rider_user_id FROM public.riders WHERE id = NEW.rider_id;

        IF v_rider_user_id IS NOT NULL THEN
            SELECT order_type::text INTO v_order_type FROM public.orders WHERE id = NEW.order_id;

            IF v_order_type IN ('intercity_ride', 'intercity_parcel') THEN
                v_notification_type := 'intercity_order_assignment';
            END IF;

            PERFORM public.send_push_notification_fnc(
                v_rider_user_id,
                'New Order Request',
                'You have a new order request nearby!',
                jsonb_build_object(
                    'type', v_notification_type,
                    'order_id', NEW.order_id,
                    'assignment_id', NEW.id
                )
            );
        END IF;
    END IF;

    RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.prevent_local_ride_assignment_to_busy_rider()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    v_new_order_type text;
    v_new_distance integer;
BEGIN
    IF NEW.assignment_status IS DISTINCT FROM 'sent' THEN
        RETURN NEW;
    END IF;

    SELECT o.order_type::text, o.distance_meters
    INTO v_new_order_type, v_new_distance
    FROM public.orders o
    WHERE o.id = NEW.order_id;

    -- Only local rides are in scope for this guard.
    IF v_new_order_type IS DISTINCT FROM 'ride' OR COALESCE(v_new_distance, 0) > 20000 THEN
        RETURN NEW;
    END IF;

    IF EXISTS (
        SELECT 1
        FROM public.orders bo
        WHERE bo.rider_id = NEW.rider_id
          AND bo.id != NEW.order_id
          AND bo.order_type = 'ride'
          AND COALESCE(bo.distance_meters, 0) <= 20000
          AND bo.order_status IN ('accepted', 'rider_arrived', 'picked_up', 'ongoing', 'payment_pending')
    ) THEN
        RETURN NULL;
    END IF;

    RETURN NEW;
END;
$function$
